"""Library of Congress Name Authority File (LC-NAF) Standard Roster.

Contains authorized heading records, dates, variant name forms, and cross-references.
"""

from typing import Dict, List, Optional
from dataclasses import dataclass, field


@dataclass
class NameAuthorityRecord:
    lccn: str
    authorized_heading: str
    dates: str
    fuller_form: str
    see_from_variants: List[str] = field(default_factory=list)
    corporate_affiliations: List[str] = field(default_factory=list)
    biographical_note: str = ""


NAME_AUTHORITY_REGISTRY: Dict[str, NameAuthorityRecord] = {}

def _auth(lccn: str, heading: str, dates: str, fuller: str, variants: List[str], affils: List[str], note: str):
    NAME_AUTHORITY_REGISTRY[lccn] = NameAuthorityRecord(lccn, heading, dates, fuller, variants, affils, note)

