def lookup_authority_record(lccn_or_heading: str) -> Optional[NameAuthorityRecord]:
    clean = lccn_or_heading.strip().lower()
    for rec in NAME_AUTHORITY_REGISTRY.values():
        if rec.lccn.lower() == clean or rec.authorized_heading.lower() == clean:
            return rec
    return None

def search_authorities(query: str, limit: int = 25) -> List[NameAuthorityRecord]:
    q = query.strip().lower()
    matches = []
    for rec in NAME_AUTHORITY_REGISTRY.values():
        if q in rec.authorized_heading.lower():
            matches.append(rec)
            if len(matches) >= limit:
                break
    return matches
